        results: d1.prepare(sql).all(...(binds as Array<null | string | number>)) as Array<T>,
      })),
    run: () =>
      Effect.sync(() => {
        d1.prepare(sql).run(...(binds as Array<null | string | number>));
        return { results: [] };
      }),
  });

  const queryDb = {
